import{_ as a,o as t,c as s,a3 as r}from"./chunks/framework.BZCmpA0A.js";const m=JSON.parse('{"title":"03 · 例外與系統呼叫","description":"","frontmatter":{},"headers":[],"relativePath":"topics/traps.md","filePath":"topics/traps.md","lastUpdated":1793085054000}'),c={name:"topics/traps.md"};function d(p,e,l,n,o,i){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="_03-·-例外與系統呼叫" tabindex="-1">03 · 例外與系統呼叫 <a class="header-anchor" href="#_03-·-例外與系統呼叫" aria-label="Permalink to &quot;03 · 例外與系統呼叫&quot;">​</a></h1><p>User Mode（使用者模式）程式不能直接控制所有硬體。它以 syscall（系統呼叫）請核心提供服務；CPU 偵測到非法存取或缺頁時，也會進入核心。</p><h2 id="cpu-如何進入入口" tabindex="-1">CPU 如何進入入口 <a class="header-anchor" href="#cpu-如何進入入口" aria-label="Permalink to &quot;CPU 如何進入入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名稱</th><th>用途</th></tr></thead><tbody><tr><td>stvec（監督模式陷阱向量暫存器）</td><td>指定陷阱入口與入口模式</td></tr><tr><td>scause（監督模式陷阱原因暫存器）</td><td>記錄發生哪種事件</td></tr><tr><td>sepc（監督模式例外指令位置暫存器）</td><td>保存返回／重試時的指令位置</td></tr><tr><td>stval（監督模式陷阱額外資訊暫存器）</td><td>缺頁時通常提供相關虛擬位址</td></tr><tr><td>sscratch（監督模式暫存用途暫存器）</td><td>WUWAOS 用於切換使用者與核心堆疊</td></tr></tbody></table><p>本核心的 stvec 採 Direct mode（共同入口模式），所有委派給監督模式的陷阱先到同一個 <code>trap_entry</code>，再由軟體依原因分派。不是每種例外都有一個硬體向量表項。</p><h2 id="trap-s-與-trap-c-的關係" tabindex="-1">trap.S 與 trap.c 的關係 <a class="header-anchor" href="#trap-s-與-trap-c-的關係" aria-label="Permalink to &quot;trap.S 與 trap.c 的關係&quot;">​</a></h2><p><code>kernel/trap.S</code> 先切換堆疊，將一般暫存器和 CSR（控制與狀態暫存器）存入 288-byte TrapFrame（暫存器保存結構），再呼叫 C 的 <code>trap_handler</code>。</p><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/trap.c" target="_blank" rel="noreferrer">kernel/trap.c（GitHub）</a>。</p><p>CPU 不會自動幫核心保存全部一般暫存器。若不先保存，C 處理函式就可能破壞使用者原有資料。C 最後回傳要恢復的 TrapFrame，組合語言還原後用 <code>sret</code> 返回使用者模式。</p><p>陷阱處理期間若要切換行程，另由 swtch.S 保存核心呼叫上下文，經獨立排程器堆疊切換；之後恢復同一行程的 C 呼叫，再回到它自己的 trap.S 返回路徑。TrapFrame 與 KernelContext 的分工見<a href="./processes.html#核心函式如何暫停與恢復">行程管理</a>。</p><h2 id="一次系統呼叫" tabindex="-1">一次系統呼叫 <a class="header-anchor" href="#一次系統呼叫" aria-label="Permalink to &quot;一次系統呼叫&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shell 呼叫 API → a7 放呼叫編號、a0… 放參數</span></span>
<span class="line"><span>  → ecall → trap_entry → trap_handler → syscall_dispatch</span></span>
<span class="line"><span>  → 服務函式 → a0 放結果 → sret</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>user/api.c</code> 的 <code>syscall3</code> 負責暫存器約定，<code>include/syscall_numbers.h</code> 定義編號，<code>kernel/syscall.c</code> 分派。Shell 的 <code>cat</code>、<code>fan</code> 是使用者層命令名稱，不等於各自都有同名 syscall。</p><p>ecall（環境呼叫指令）長度固定 4 bytes；核心將 sepc 加 4，讓返回時從呼叫後繼續。缺頁補頁成功則保留原 sepc，重試同一指令，兩者不可混用。</p><h2 id="如何觀察" tabindex="-1">如何觀察 <a class="header-anchor" href="#如何觀察" aria-label="Permalink to &quot;如何觀察&quot;">​</a></h2><p>在 <code>wuwaos&gt;</code> 執行 <code>ps</code>，命令經 API 進核心，讀取真實 PCB，再輸出結果。執行 <code>mem alloc 1</code>、<code>mem read 0</code>，則可配合 <code>vmstat</code> 觀察合法首次存取的<a href="./paging.html">缺頁處理</a>。</p><p>計時器中斷也走同一入口：scause 最高位表示中斷、低位原因 5 表示監督模式計時器。先清除 pending，再讓原行程排到隊尾，依 <a href="./scheduling.html">RR 排程</a> 選擇下一個；保留 sepc 與 a0，不當作 syscall 返回值改寫。</p><p>核心自身出錯目前會印出陷阱資訊並停止；使用者非法存取則結束該行程。目前已有計時器驅動的 50 ms RR，但 UART 仍輪詢，也沒有完整訊號機制或核心內搶占。</p><p>觀念參考：<code>notes/ch2 Operating-System Structures.md</code> 的系統呼叫與雙模式。早期基礎驗收見 <a href="./../SPEC-01-user-syscalls.html">Spec 01</a>，目前缺頁路徑見 <a href="./../SPEC-10-demand-paging.html">Spec 10</a>。</p>`,19)])])}const u=a(c,[["render",d]]);export{m as __pageData,u as default};
